shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const file = 'src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts';
let code = fs.readFileSync(file, 'utf8');

code = code.replace(
  /const promptBuilder = new PromptBuilder\(\{\s*baseSystemPrompt: 'You are HAL\.',\s*systemPromptSuffix: 'Be precise\.',\s*contextConfig: \{\s*historyLength: 10,\s*includeTimestamps: false,\s*includeSystemPrompt: true,\s*\},\s*\}\);/,
  "const promptBuilder = new PromptBuilder({\n  identity: 'You are HAL.',\n});"
);

const oldExpects = `    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
      'Database connection failed in beforeSession'
    );

    expect(caughtError).toBe(errorToThrow);
    expect(afterSessionRan).toBe(true);`;

const newExpects = `    let thrownError: Error | undefined;
    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (e) {
      thrownError = e as Error;
    }

    expect({
      thrown: thrownError,
      caught: caughtError,
      afterSessionRan,
    }).toEqual({
      thrown: errorToThrow,
      caught: errorToThrow,
      afterSessionRan: true,
    });`;

code = code.replace(oldExpects, newExpects);
fs.writeFileSync(file, code);
EOF
node patch.js
